def get_applicable_standards(workers_count: int, risk_level: int) -> list:
    """Returns list of standard codes applicable based on company classification.
    Cap 1 (Art. 3): <=10 trab. riesgo I-III -> 7 estándares
    Cap 2 (Art. 9): 11-50 trab. riesgo I-III -> 21 estándares
    Cap 3 (Art. 16): >50 trab. (cualquier riesgo) o <=50 riesgo IV-V -> 60 estándares
    """
    is_cap3 = workers_count > 50 or risk_level >= 4
    if is_cap3:
        return [s["code"] for s in STANDARDS_BANK]
    if workers_count <= 10:
        return [s["code"] for s in STANDARDS_BANK if s["code"] in CAP1_CODES]
    return [s["code"] for s in STANDARDS_BANK if s["code"] in CAP2_CODES]

def get_total_weight(standards_codes: list) -> float:
    total = 0
    for s in STANDARDS_BANK:
        if s["code"] in standards_codes:
            total += s["weight"]
    return round(total, 2)


# ==================== MOTOR DE CALIFICACIÓN RES. 0312 ====================
# Lógica del Excel: Si cumple = puntaje máximo del item.
# Si no cumple = 0. Si no aplica = puntaje máximo (justificado).

