def calculate_score(checklist_items: list) -> dict:
    """
    Calculate compliance score based on Res 0312 evaluation logic.
    Returns breakdown by item, standard, cycle PHVA, and total.
    Logic: cumple = max_score, no_cumple = 0, parcial = 0, no_aplica = max_score (justified)
    """
    total_possible = 0
    total_obtained = 0
    by_cycle = {}
    by_standard = {}
    items_detail = []

    for item in checklist_items:
        code = item.get("code", "")
        result = item.get("result", "")
        max_score = item.get("weight", 0)

        # Find the standard definition
        std_def = next((s for s in STANDARDS_BANK if s["code"] == code), None)
        if std_def:
            max_score = std_def["weight"]

        # Calculate score based on result
        if result == "cumple":
            score = max_score
        elif result == "no_aplica":
            score = max_score  # No aplica = puntaje máximo (si se justifica)
        else:
            score = 0  # no_cumple, parcial, or empty

        total_possible += max_score
        total_obtained += score

        # Group by cycle
        phva = item.get("phva", std_def["phva"] if std_def else "")
        if phva not in by_cycle:
            by_cycle[phva] = {"possible": 0, "obtained": 0, "items": 0, "cumple": 0, "no_cumple": 0, "parcial": 0, "no_aplica": 0, "pending": 0}
        by_cycle[phva]["possible"] += max_score
        by_cycle[phva]["obtained"] += score
        by_cycle[phva]["items"] += 1
        if result == "cumple":
            by_cycle[phva]["cumple"] += 1
        elif result == "no_cumple":
            by_cycle[phva]["no_cumple"] += 1
        elif result == "parcial":
            by_cycle[phva]["parcial"] += 1
        elif result == "no_aplica":
            by_cycle[phva]["no_aplica"] += 1
        else:
            by_cycle[phva]["pending"] += 1

        # Group by standard
        std_name = item.get("standard", std_def["standard"] if std_def else "")
        if std_name not in by_standard:
            by_standard[std_name] = {"possible": 0, "obtained": 0, "items": 0}
        by_standard[std_name]["possible"] += max_score
        by_standard[std_name]["obtained"] += score
        by_standard[std_name]["items"] += 1

        items_detail.append({
            "code": code,
            "max_score": max_score,
            "score": score,
            "result": result,
        })

    # Calculate percentages
    pct = round((total_obtained / total_possible * 100) if total_possible > 0 else 0, 2)

    # Classification
    classification = CLASSIFICATION_THRESHOLDS[0]  # default critical
    for t in CLASSIFICATION_THRESHOLDS:
        if t["min"] <= pct <= t["max"]:
            classification = t
            break

    # Cycle percentages
    cycle_summary = {}
    for cycle, data in by_cycle.items():
        data["pct"] = round((data["obtained"] / data["possible"] * 100) if data["possible"] > 0 else 0, 2)
        cycle_summary[cycle] = data

    # Standard percentages
    std_summary = {}
    for std, data in by_standard.items():
        data["pct"] = round((data["obtained"] / data["possible"] * 100) if data["possible"] > 0 else 0, 2)
        std_summary[std] = data

    return {
        "total_possible": round(total_possible, 2),
        "total_obtained": round(total_obtained, 2),
        "percentage": pct,
        "classification": {
            "level": classification["level"],
            "label": classification["label"],
            "color": classification["color"],
            "action": classification["action"],
        },
        "by_cycle": cycle_summary,
        "by_standard": std_summary,
    }


