PESV_PHASES = {
    "PLANIFICACION": {"label": "Fase 1. Planificacion del PESV", "weight_pct": 35},
    "IMPLEMENTACION": {"label": "Fase 2. Implementacion y Ejecucion del PESV", "weight_pct": 30},
    "SEGUIMIENTO": {"label": "Fase 3. Seguimiento, Evaluacion y Mejora", "weight_pct": 20},
    "MEJORA": {"label": "Fase 4. Mejora Continua", "weight_pct": 15},
}

def get_pesv_standards(level="avanzado"):
    """Get applicable PESV standards by level: basico, estandar, avanzado"""
    key = f"nivel_{level}"
    return [s for s in PESV_STANDARDS if s.get(key, True)]

def calculate_pesv_score(checklist_items):
    """Calculate PESV compliance score"""
    total = len(checklist_items)
    if total == 0:
        return {"percentage": 0, "total_items": 0}
    cumple = sum(1 for c in checklist_items if c.get("result") == "cumple")
    no_aplica = sum(1 for c in checklist_items if c.get("result") == "no_aplica")
    evaluable = total - no_aplica
    pct = round((cumple / evaluable * 100) if evaluable > 0 else 0, 2)
    by_fase = {}
    for item in checklist_items:
        fase = item.get("fase", item.get("phva", ""))
        if fase not in by_fase:
            by_fase[fase] = {"total": 0, "cumple": 0, "no_cumple": 0, "parcial": 0, "no_aplica": 0, "pending": 0}
        by_fase[fase]["total"] += 1
        r = item.get("result", "")
        if r == "cumple": by_fase[fase]["cumple"] += 1
        elif r == "no_cumple": by_fase[fase]["no_cumple"] += 1
        elif r == "parcial": by_fase[fase]["parcial"] += 1
        elif r == "no_aplica": by_fase[fase]["no_aplica"] += 1
        else: by_fase[fase]["pending"] += 1
    for fase, data in by_fase.items():
        ev = data["total"] - data["no_aplica"]
        data["pct"] = round((data["cumple"] / ev * 100) if ev > 0 else 0, 2)
    classification = {"level": "CRITICO", "label": "Critico", "color": "#D90429", "action": "Requiere plan de mejoramiento inmediato del PESV."}
    if pct >= 85:
        classification = {"level": "ACEPTABLE", "label": "Aceptable", "color": "#2A9D8F", "action": "Mantener y mejorar continuamente el PESV."}
    elif pct >= 60:
        classification = {"level": "MODERADO", "label": "Moderadamente Aceptable", "color": "#FFC300", "action": "Realizar plan de mejoramiento del PESV en maximo 6 meses."}
    return {"percentage": pct, "total_items": total, "evaluable": evaluable, "cumple": cumple, "no_aplica": no_aplica, "classification": classification, "by_fase": by_fase}
